<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowRight, ArrowDown, ChatDotRound, Document, FolderOpened, List, Collection, Calendar, Bell, Clock, MagicStick, Plus, Search, RefreshLeft, Promotion, CircleCheck, Lock, MoreFilled, Connection, InfoFilled } from '@element-plus/icons-vue'
import DemoRunCard from './DemoRunCard.vue'
import { createDemoState, createDemoRun, confirmDemoProposal, demoId, nowLabel, members, statusOptions, type DemoTab, type DemoRun, type DemoTask, type DemoRequirement, type DemoKnowledge } from './state'

const state = reactive(createDemoState())
const active = ref<DemoTab>('coo')
const nav = [
  { id: 'coo' as const, name: 'Coo AI 同事', icon: MagicStick },
  { id: 'requirements' as const, name: '需求管理', icon: Document },
  { id: 'tasks' as const, name: '团队任务', icon: List },
  { id: 'knowledge' as const, name: '知识库', icon: Collection },
  { id: 'versions' as const, name: '版本排期', icon: Calendar },
  { id: 'events' as const, name: '主动工作', icon: Bell },
  { id: 'runs' as const, name: '执行记录', icon: Clock },
]
const pageTitle = computed(() => nav.find(item => item.id === active.value)?.name)
const taskCount = computed(() => state.tasks.filter(task => task.status !== '已完成').length)
const doneCount = computed(() => state.tasks.filter(task => task.status === '已完成').length)
const knowledgeCount = computed(() => state.knowledge.filter(doc => doc.published).length)
const chatScroll = ref<HTMLElement>()
const scrollToLatest = async () => { await nextTick(); chatScroll.value?.scrollTo({ top: chatScroll.value.scrollHeight, behavior: 'smooth' }) }
onMounted(scrollToLatest)
const busy = ref(false), message = ref(''), allowAuto = ref(false), tour = ref(false), projectInfo = ref(false)
watch(() => [state.runs.length, busy.value, active.value], () => { if(active.value==='coo')void scrollToLatest() })
const taskQuery = ref(''), taskLayout = ref<'board'|'list'>('board')
const filteredTasks = computed(() => state.tasks.filter(task => `${task.name}${task.assignee}${task.id}`.includes(taskQuery.value)))
let epoch = 0
const timers = new Set<ReturnType<typeof setTimeout>>()
const later = (fn: () => void, ms: number) => { const version = epoch; const timer = setTimeout(() => { timers.delete(timer); if (version === epoch) fn() }, ms); timers.add(timer) }
const stopTimers = () => { epoch++; timers.forEach(clearTimeout); timers.clear() }
onBeforeUnmount(stopTimers)

const taskDrawer = ref(false), selectedTaskId = ref('')
const selectedTask = computed(() => state.tasks.find(task => task.id === selectedTaskId.value))
const taskForm = reactive({ name: '', assignee: '王磊', status: '未开始' as DemoTask['status'], priority: 'P1', description: '', due: '2026-10-30' })
const comment = ref(''), replyTo = ref<string|null>(null)
const openTask = (id: string) => { const task = state.tasks.find(row => row.id === id); if (!task) return; selectedTaskId.value = id; Object.assign(taskForm, task); comment.value = ''; replyTo.value = null; taskDrawer.value = true }
const saveTask = () => { if (!selectedTask.value || !taskForm.name.trim()) return; Object.assign(selectedTask.value, taskForm, {name:taskForm.name.trim()}); ElMessage.success('演示任务已更新') }
const postComment = () => { if (!selectedTask.value || !comment.value.trim()) return; selectedTask.value.comments.push({id:demoId('COMMENT'),author:'林晓',ai:false,content:comment.value.trim(),time:nowLabel(),parentId:replyTo.value}); comment.value='';replyTo.value=null;ElMessage.success('留言已加入演示任务') }
const newTaskDialog = ref(false)
const newTask = reactive({ name:'', assignee:'王磊', description:'', due:'2026-10-30' })
const addTask = () => { if (!newTask.name.trim()) return; const id=demoId('TASK');state.tasks.unshift({id,...newTask,status:'未开始',priority:'P1',comments:[]});newTaskDialog.value=false;newTask.name='';newTask.description='';openTask(id) }

const runDrawer = ref(false), selectedRunId = ref('')
const selectedRun = computed(() => state.runs.find(run => run.id === selectedRunId.value))
const openRun = (id:string) => {selectedRunId.value=id;runDrawer.value=true}
const confirm = (run:DemoRun) => { const id=confirmDemoProposal(state,run); if(id)ElMessage.success(run.proposal?.kind==='task'?'任务已加入演示看板':run.proposal?.kind==='comment'?'Coo 留言已发送（演示）':'演示任务状态已更新') }
const reject = (run:DemoRun) => {if(run.proposal?.status==='pending')run.proposal.status='rejected'}
const proposalDialog = ref(false), editingRunId = ref('')
const proposalForm = reactive({title:'',assignee:'王磊',content:'',due:'2026-10-30',taskStatus:'进行中' as DemoTask['status']})
const editProposal = (run:DemoRun) => {if(!run.proposal)return;editingRunId.value=run.id;Object.assign(proposalForm,run.proposal);proposalDialog.value=true}
const saveProposal = () => {const run=state.runs.find(row=>row.id===editingRunId.value);if(run?.proposal?.status!=='pending'||!proposalForm.title.trim())return;Object.assign(run.proposal,proposalForm);proposalDialog.value=false;ElMessage.success('建议已调整，等待你确认')}
const playRun = (run:DemoRun, eventId?:string) => {
  // Timed playback must mutate the same reactive object rendered by both views.
  run=reactive(run)
  state.runs.push(run);busy.value=true
  const auto=allowAuto.value
  run.steps.forEach((step,index)=>later(()=>{if(index>0)run.steps[index-1]!.status='done';step.status='running'},180+index*440))
  later(()=>{run.steps.forEach(step=>{step.status='done'});run.status='done';busy.value=false;allowAuto.value=false;const event=state.events.find(row=>row.id===eventId);if(event)event.status='待确认';if(auto&&run.proposal?.kind==='comment')confirm(run)},2150)
}
const runExample = (kind:'investigate'|'knowledge'|'comment'|'status',goal:string) => {if(busy.value)return;active.value='coo';message.value='';playRun(createDemoRun(kind,goal))}
const send = () => {
  if(!message.value.trim()||busy.value)return
  const goal=message.value.trim()
  const kind=/留言|回复/.test(goal)?'comment':/状态|进行中|已完成/.test(goal)?'status':/规范|知识/.test(goal)&&!/任务|安排|调查|跟进/.test(goal)?'knowledge':'investigate'
  runExample(kind,goal)
}
const investigateEvent = (id:string) => {if(busy.value)return;const event=state.events.find(row=>row.id===id);if(!event||event.status!=='待处理')return;const run=createDemoRun('investigate',`调查模拟订单 ${event.order} 的超时未发货异常，并准备内部跟进任务。`,'业务事件',event.order);event.runId=run.id;event.status='调查中';playRun(run,id);openRun(run.id)}
const simulateEvent = () => {const id=demoId('EVENT');state.events.unshift({id,order:`DEMO-${String(state.events.length+847).padStart(4,'0')}`,title:'订单超时未发货',status:'待处理',runId:null,time:nowLabel()});ElMessage.success('已添加一条模拟履约异常，点击「播放调查」查看过程')}

const requirementDrawer=ref(false), requirementDialog=ref(false), selectedRequirementId=ref(''), analyzing=ref(false)
const selectedRequirement=computed(()=>state.requirements.find(row=>row.id===selectedRequirementId.value))
const requirementForm=reactive({title:'',raw:''})
const openRequirement=(id:string)=>{selectedRequirementId.value=id;requirementDrawer.value=true}
const addRequirement=()=>{if(!requirementForm.title.trim()||!requirementForm.raw.trim())return;const id=demoId('REQ');state.requirements.unshift({id,title:requirementForm.title,raw:requirementForm.raw,status:'待分析',priority:'待评估',type:'待分析',goal:'',summary:''});requirementDialog.value=false;requirementForm.title='';requirementForm.raw='';openRequirement(id)}
const analyze=(row:DemoRequirement)=>{if(analyzing.value)return;analyzing.value=true;later(()=>{row.status='已分析';row.priority='P1';row.type='新增功能';row.goal='让业务异常及时被发现，明确负责人并持续记录跟进进展。';row.summary='预设分析样例：场景与目标明确，建议先完成发现异常、创建跟进任务与记录进展的最小闭环。';analyzing.value=false;ElMessage.success('预设分析样例已展示，未调用模型')},850)}

const knowledgeDrawer=ref(false),selectedKnowledgeId=ref(''),knowledgeQuery=ref(''),recallDialog=ref(false),recallQuery=ref('订单超时未发货应该如何处理？'),recallDone=ref(false),knowledgeDialog=ref(false)
const selectedKnowledge=computed(()=>state.knowledge.find(doc=>doc.id===selectedKnowledgeId.value))
const filteredKnowledge=computed(()=>state.knowledge.filter(doc=>`${doc.title}${doc.category}${doc.content}`.includes(knowledgeQuery.value)))
const knowledgeForm=reactive({title:'',content:'',scope:'项目成员'})
const openKnowledge=(id:string)=>{selectedKnowledgeId.value=id;knowledgeDrawer.value=true}
const addKnowledge=()=>{if(!knowledgeForm.title.trim()||!knowledgeForm.content.trim())return;state.knowledge.unshift({id:demoId('KB'),title:knowledgeForm.title,content:knowledgeForm.content,scope:knowledgeForm.scope,category:'履约协作',version:1,published:false,updated:'今天'});knowledgeDialog.value=false;knowledgeForm.title='';knowledgeForm.content='';ElMessage.success('演示草稿已创建')}
const publishKnowledge=(doc:DemoKnowledge)=>{doc.published=!doc.published;ElMessage.success(doc.published?'已切换为发布状态，仅演示发布交互':'演示知识已停用')}
const versionPercent=computed(()=>Math.round(doneCount.value/state.tasks.length*100))
const barWidth=(due:string)=>`${Math.max(18,Math.min(97,((Date.parse(due)-Date.parse('2026-10-28'))/86400000+1)/7*100))}%`
const reset = async () => {try{await ElMessageBox.confirm('当前页面的演示修改会恢复为初始样例。','重置交互演示',{confirmButtonText:'重置',cancelButtonText:'取消',type:'info'})}catch{return}stopTimers();Object.assign(state,createDemoState());busy.value=false;analyzing.value=false;message.value='';allowAuto.value=false;taskDrawer.value=false;requirementDrawer.value=false;knowledgeDrawer.value=false;runDrawer.value=false;proposalDialog.value=false;active.value='coo';ElMessage.success('演示已重置')}
</script>

<template>
  <div class="coo-demo-shell">
    <aside class="demo-sidebar">
      <div class="demo-brand"><span class="brand-glyph"><i/><i/><i/><i/></span><div><strong>Coo</strong><small>企业 AI 协作系统</small></div><span class="version-tag">V4.0</span></div>
      <button class="demo-project" @click="projectInfo=true"><span class="project-glyph"><el-icon><FolderOpened/></el-icon></span><span><strong>电商履约协作</strong><small>团队空间</small></span><el-icon><ArrowDown/></el-icon></button>
      <div class="nav-label">工作空间</div>
      <nav><button v-for="item in nav" :key="item.id" :aria-label="item.name" :title="item.name" :class="{active:active===item.id}" @click="active=item.id"><el-icon><component :is="item.icon"/></el-icon><span>{{item.name}}</span><small v-if="item.id==='tasks'">{{taskCount}}</small><small v-if="item.id==='requirements'">{{state.requirements.length}}</small><span v-if="item.id==='events' && state.events.some(event=>event.status==='待处理')" class="notice-dot"/><span v-if="item.id==='coo'" class="nav-ai">AI</span></button></nav>
      <div class="sidebar-note"><span class="live-dot"/><strong>一个 Coo，与整个团队协作</strong><p>连接业务上下文，让每一次跟进都有迹可循。</p></div>
      <div class="demo-profile"><span class="avatar blue">林</span><div><strong>林晓</strong><small>产品经理 · 演示身份</small></div><el-icon><MoreFilled/></el-icon></div>
    </aside>
    <div class="demo-main">
      <header class="demo-topbar"><div class="demo-breadcrumb">电商履约协作 <el-icon><ArrowRight/></el-icon><strong>{{pageTitle}}</strong></div><div class="topbar-right"><span class="demo-pill"><span/>交互演示 · 全部为假数据</span><button aria-label="演示指南" @click="tour=true"><el-icon><InfoFilled/></el-icon>演示指南</button><button aria-label="重置演示" @click="reset"><el-icon><RefreshLeft/></el-icon>重置演示</button></div></header>
      <div class="demo-notice"><el-icon><InfoFilled/></el-icon><span>这是纯前端交互样例，不需要登录。AI 回复与执行过程均为预设演示，不调用后端或模型；刷新即可重置。</span></div>
      <main class="demo-workspace" :class="{'chat-workspace':active==='coo'}">
        <template v-if="active==='coo'">
          <div class="demo-chat">
            <div class="chat-page-heading"><div><div class="eyebrow">YOUR AI TEAMMATE</div><h1>和 Coo 一起推进工作<span class="coo-spark">✦</span></h1><p>从理解问题到行动跟进，和团队共享同一份业务上下文。</p></div><span class="private-label"><el-icon><Lock/></el-icon>私人会话</span></div>
            <div class="conversation-actions"><span class="conversation-date">今天 · 电商履约协作</span><button @click="runExample('knowledge','查询订单超时未发货的处理规范。')" :disabled="busy"><el-icon><Plus/></el-icon>新建示例对话</button></div>
            <div ref="chatScroll" class="demo-conversation"><div v-for="run in state.runs" :key="run.id" class="demo-turn"><div class="user-turn"><span>{{run.goal}}</span><span class="avatar mini blue">林</span></div><DemoRunCard :run="run" @confirm="confirm" @reject="reject" @edit="editProposal" @task="openTask" @knowledge="openKnowledge"/></div></div>
            <div class="demo-composer"><div class="prompt-shortcuts"><button :disabled="busy" @click="runExample('knowledge','查询订单超时未发货的处理规范。')"><el-icon><Search/></el-icon>查找处理规范</button><button :disabled="busy" @click="runExample('comment','查看仓储任务的进展，帮我准备一条跟进留言。')"><el-icon><ChatDotRound/></el-icon>跟进任务留言</button><button :disabled="busy" @click="runExample('status','将仓储调查任务更新为进行中。')"><el-icon><CircleCheck/></el-icon>更新任务状态</button></div><el-input v-model="message" type="textarea" :rows="2" resize="none" placeholder="告诉 Coo 你想推进什么，例如：调查订单延迟，并准备跟进任务…" :disabled="busy" @keydown.ctrl.enter.prevent="send"/><div class="composer-bottom"><el-checkbox v-model="allowAuto" :disabled="busy">本轮允许自动发表低风险留言</el-checkbox><el-button type="primary" :icon="Promotion" :loading="busy" :disabled="!message.trim()" @click="send">{{busy?'播放中':'发送'}}</el-button></div><p class="composer-caption">预设交互样例 · 不会调用模型，也不会改变真实业务数据</p></div>
          </div>
          <aside class="demo-context"><div class="context-heading"><span>当前业务上下文</span><el-icon><Connection/></el-icon></div><section class="context-block"><span class="context-label">当前项目</span><h3>电商履约协作</h3><p>发现履约异常，协调仓储与客服，持续跟进处理进度。</p><div class="context-members"><span class="avatar tiny blue">林</span><span class="avatar tiny violet">陈</span><span class="avatar tiny teal">王</span><span>3 位项目成员</span></div></section><section class="context-block"><div class="context-label with-badge">关联业务事件 <span>模拟 ERP</span></div><div class="order-info"><strong>DEMO-0846</strong><span class="warning-label">超时未发货</span></div><div class="order-row"><span>等待发货</span><b class="warning-text">72 小时</b></div><div class="order-row"><span>所属仓库</span><b>杭州一号仓</b></div><div class="order-row"><span>仓储协调</span><b>王磊</b></div><button class="context-link" @click="active='events'">查看业务事件 <el-icon><ArrowRight/></el-icon></button></section><section class="context-block"><span class="context-label">可用业务信息</span><button class="context-resource" @click="active='requirements'"><el-icon><Document/></el-icon>项目需求<span>{{state.requirements.length}}</span></button><button class="context-resource" @click="active='tasks'"><el-icon><List/></el-icon>待完成任务<span>{{taskCount}}</span></button><button class="context-resource" @click="active='knowledge'"><el-icon><Collection/></el-icon>有效知识<span>{{knowledgeCount}}</span></button></section><section class="context-safety"><el-icon><Lock/></el-icon><div><strong>行动前，由你确认</strong><p>Coo 的任务建议可以先调整，再决定是否执行。</p></div></section><div class="context-footer">样例快照 · 2026 年 10 月 29 日</div></aside>
        </template>

        <section v-else-if="active==='tasks'" class="demo-page">
          <div class="demo-page-heading"><div><div class="eyebrow">TEAM COLLABORATION</div><h1>团队任务 <small>{{state.tasks.length}}</small></h1><p>任务、进展与讨论，放在一起跟进。</p></div><el-button type="primary" :icon="Plus" @click="newTaskDialog=true">新建任务</el-button></div>
          <div class="demo-toolbar"><el-input v-model="taskQuery" :prefix-icon="Search" placeholder="搜索任务或负责人" clearable/><el-radio-group v-model="taskLayout"><el-radio-button value="board">看板</el-radio-button><el-radio-button value="list">列表</el-radio-button></el-radio-group></div>
          <div v-if="taskLayout==='board'" class="demo-kanban"><div v-for="status in statusOptions" :key="status" class="demo-lane"><div class="lane-heading"><span class="status-dot" :class="status==='进行中'?'progress':status==='已完成'?'done':''"/><strong>{{status}}</strong><small>{{filteredTasks.filter(task=>task.status===status).length}}</small><button aria-label="添加演示任务" @click="newTaskDialog=true"><el-icon><Plus/></el-icon></button></div><button v-for="task in filteredTasks.filter(row=>row.status===status)" :key="task.id" class="demo-task-card" @click="openTask(task.id)"><div class="task-top"><small>{{task.id}}</small><span class="task-priority" :class="task.priority">{{task.priority}}</span></div><h3>{{task.name}}</h3><p>{{task.description}}</p><div v-if="task.fromCoo" class="task-coo"><el-icon><MagicStick/></el-icon>Coo 协作创建</div><div class="task-card-bottom"><span class="avatar tiny" :class="task.assignee==='王磊'?'teal':task.assignee==='陈佳'?'violet':'blue'">{{task.assignee.slice(0,1)}}</span><span>{{task.assignee}}</span><small>{{task.due.slice(5).replace('-','/')}}</small><span v-if="task.comments.length" class="comment-count"><el-icon><ChatDotRound/></el-icon>{{task.comments.length}}</span></div></button><div v-if="!filteredTasks.some(task=>task.status===status)" class="lane-empty">暂时没有任务</div></div></div>
          <el-table v-else :data="filteredTasks" @row-click="(row:DemoTask)=>openTask(row.id)"><el-table-column prop="name" label="任务名称" min-width="240"/><el-table-column prop="assignee" label="负责人"/><el-table-column prop="status" label="状态"/><el-table-column prop="priority" label="优先级"/><el-table-column prop="due" label="截止日期"/><el-table-column label="留言"><template #default="{row}">{{row.comments.length}}</template></el-table-column></el-table>
        </section>

        <section v-else-if="active==='requirements'" class="demo-page"><div class="demo-page-heading"><div><div class="eyebrow">REQUIREMENTS</div><h1>需求管理</h1><p>保留原始想法，让 Coo 协助梳理目标与下一步。</p></div><el-button type="primary" :icon="Plus" @click="requirementDialog=true">创建需求</el-button></div><div class="demo-stats"><div><span>项目需求</span><strong>{{state.requirements.length}}</strong></div><div><span>已完成分析</span><strong>{{state.requirements.filter(row=>row.status==='已分析').length}}</strong></div><div><span>等待分析</span><strong>{{state.requirements.filter(row=>row.status==='待分析').length}}</strong></div></div><el-table :data="state.requirements" @row-click="(row:DemoRequirement)=>openRequirement(row.id)"><el-table-column prop="id" label="编号" width="130"/><el-table-column prop="title" label="需求" min-width="280"/><el-table-column prop="type" label="类型"/><el-table-column label="分析状态"><template #default="{row}"><span class="soft-tag" :class="row.status==='已分析'?'green':'gray'">{{row.status}}</span></template></el-table-column><el-table-column prop="priority" label="优先级"/><el-table-column label="操作"><template #default="{row}"><el-button text type="primary" @click.stop="openRequirement(row.id)">查看详情</el-button></template></el-table-column></el-table></section>

        <section v-else-if="active==='knowledge'" class="demo-page"><div class="demo-page-heading"><div><div class="eyebrow">COMPANY KNOWLEDGE</div><h1>业务知识库</h1><p>让经验成为可引用、可更新的团队知识。</p></div><div><el-button :icon="Search" @click="recallDialog=true;recallDone=false">召回测试</el-button><el-button type="primary" :icon="Plus" @click="knowledgeDialog=true">创建知识</el-button></div></div><div class="demo-toolbar"><el-input v-model="knowledgeQuery" :prefix-icon="Search" placeholder="搜索知识标题或内容" clearable/><span class="toolbar-note">{{knowledgeCount}} 篇有效知识 · 企业与项目分级访问</span></div><div class="knowledge-grid"><article v-for="doc in filteredKnowledge" :key="doc.id" class="demo-knowledge-card"><div class="kb-card-head"><span class="knowledge-glyph"><el-icon><Document/></el-icon></span><span class="soft-tag" :class="doc.published?'green':'gray'">{{doc.published?'已发布':'草稿'}}</span></div><button class="kb-title" @click="openKnowledge(doc.id)">{{doc.title}}</button><p>{{doc.content.slice(0,76)}}…</p><div class="kb-meta"><span>{{doc.category}}</span><span><el-icon><Lock/></el-icon>{{doc.scope}}</span></div><div class="kb-bottom"><small>v{{doc.version}} · {{doc.updated}}更新</small><button @click="openKnowledge(doc.id)">查看知识 <el-icon><ArrowRight/></el-icon></button></div></article></div><el-empty v-if="!filteredKnowledge.length" description="没有匹配的演示知识"/></section>

        <section v-else-if="active==='events'" class="demo-page"><div class="demo-page-heading"><div><div class="eyebrow">PROACTIVE COLLABORATION</div><h1>Coo 主动工作</h1><p>从一条业务异常开始，了解调查与协作如何发生。</p></div><el-button type="primary" :icon="Plus" :disabled="busy" @click="simulateEvent">模拟一条履约异常</el-button></div><div class="event-process"><span>业务事件</span><el-icon><ArrowRight/></el-icon><span>调查上下文</span><el-icon><ArrowRight/></el-icon><span>提出行动建议</span><el-icon><ArrowRight/></el-icon><span>员工确认</span><el-icon><ArrowRight/></el-icon><span>任务跟进</span></div><div class="demo-callout"><el-icon><InfoFilled/></el-icon>此处播放的是预设前端流程，订单为模拟 ERP 数据；页面关闭后演示停止。</div><article v-for="event in state.events" :key="event.id" class="demo-event"><span class="event-glyph"><el-icon><Bell/></el-icon></span><div class="event-body"><div><h3>{{event.title}}</h3><span class="soft-tag amber">模拟 ERP</span></div><p>订单 {{event.order}} · 已付款 72 小时 · 杭州一号仓</p><small>{{event.time}} 触发 · {{event.id}}</small></div><span class="soft-tag" :class="event.status==='已跟进'?'green':event.status==='待处理'?'gray':'blue-tag'">{{event.status}}</span><el-button v-if="event.status==='待处理'" :disabled="busy" type="primary" plain @click="investigateEvent(event.id)">播放调查</el-button><el-button v-else @click="event.runId&&openRun(event.runId)">查看调查</el-button></article></section>

        <section v-else-if="active==='versions'" class="demo-page"><div class="demo-page-heading"><div><div class="eyebrow">RELEASE PLANNING</div><h1>版本排期</h1><p>团队任务与版本共享同一份进度。</p></div><span class="soft-tag blue-tag">进行中</span></div><div class="version-overview"><div><small>当前版本</small><h2>V4.0 · 履约异常协作</h2><p>10月28日 — 11月03日 · 仓储、客服与产品共同推进</p></div><div class="version-progress"><strong>{{versionPercent}}%<small>完成</small></strong><el-progress :percentage="versionPercent" :show-text="false" color="#527ef5"/><p>{{doneCount}} / {{state.tasks.length}} 项任务完成</p></div></div><div class="demo-gantt"><div class="gantt-head"><span>任务与负责人</span><div><span v-for="day in ['28','29','30','31','01','02','03']" :key="day">{{day==='01'?'11月 ':''}}{{day}}</span></div></div><button v-for="task in state.tasks" :key="task.id" class="gantt-row" @click="openTask(task.id)"><div><strong>{{task.name}}</strong><small>{{task.assignee}}</small></div><div class="gantt-track"><span class="gantt-bar" :class="{complete:task.status==='已完成'}" :style="{width:barWidth(task.due)}">{{task.status}}</span></div></button></div><p class="demo-footnote">点击任务可修改状态或截止日期，看板与排期会同步变化。</p></section>

        <section v-else class="demo-page"><div class="demo-page-heading"><div><div class="eyebrow">ACTIVITY & TRACE</div><h1>执行记录</h1><p>查看一次协作的触发来源、处理步骤和确认结果。</p></div><span class="soft-tag gray">预设执行样例</span></div><el-table :data="[...state.runs].reverse()" @row-click="(row:DemoRun)=>openRun(row.id)"><el-table-column label="目标" min-width="360"><template #default="{row}"><strong class="run-goal">{{row.goal}}</strong><small class="run-id">{{row.id}}</small></template></el-table-column><el-table-column prop="origin" label="触发来源" width="130"/><el-table-column label="状态" width="130"><template #default="{row}"><span class="soft-tag" :class="row.status==='done'?'green':'blue-tag'">{{row.status==='done'?'已完成':'播放中'}}</span></template></el-table-column><el-table-column label="操作建议" width="130"><template #default="{row}">{{!row.proposal?'无需操作':row.proposal.status==='pending'?'等待确认':row.proposal.status==='accepted'?'已确认':'已拒绝'}}</template></el-table-column><el-table-column prop="time" label="时间" width="90"/></el-table></section>
      </main>
    </div>

    <el-drawer v-model="taskDrawer" size="560px" title="任务详情" class="demo-overlay"><template v-if="selectedTask"><div class="drawer-kicker">{{selectedTask.id}}<span v-if="selectedTask.fromCoo" class="soft-tag blue-tag">Coo 协作创建</span></div><el-form label-position="top"><el-form-item label="任务名称"><el-input v-model="taskForm.name" maxlength="200"/></el-form-item><div class="form-pair"><el-form-item label="负责人"><el-select v-model="taskForm.assignee"><el-option v-for="name in members" :key="name" :label="name" :value="name"/></el-select></el-form-item><el-form-item label="任务状态"><el-select v-model="taskForm.status"><el-option v-for="status in statusOptions" :key="status" :value="status" :label="status"/></el-select></el-form-item></div><div class="form-pair"><el-form-item label="优先级"><el-select v-model="taskForm.priority"><el-option v-for="priority in ['P0','P1','P2','P3']" :key="priority" :value="priority" :label="priority"/></el-select></el-form-item><el-form-item label="截止日期"><el-date-picker v-model="taskForm.due" value-format="YYYY-MM-DD" :clearable="false"/></el-form-item></div><el-form-item label="任务说明"><el-input v-model="taskForm.description" type="textarea" :rows="3"/></el-form-item><el-button type="primary" @click="saveTask">保存演示修改</el-button></el-form><section class="demo-comments"><h3>任务留言 <small>{{selectedTask.comments.length}}</small></h3><p v-if="!selectedTask.comments.length" class="empty-note">暂无留言，留下第一条跟进记录吧。</p><article v-for="row in selectedTask.comments" :key="row.id"><span class="avatar tiny" :class="row.ai?'coo-avatar':'blue'">{{row.ai?'✦':row.author.slice(0,1)}}</span><div><div class="comment-author"><strong>{{row.author}}</strong><span v-if="row.ai" class="soft-tag blue-tag">AI 同事</span><time>{{row.time}}</time></div><small v-if="row.parentId">回复 {{selectedTask.comments.find(parent=>parent.id===row.parentId)?.author||'一条留言'}}</small><p>{{row.content}}</p><button @click="replyTo=row.id">回复</button></div></article><div v-if="replyTo" class="reply-note">回复 {{selectedTask.comments.find(row=>row.id===replyTo)?.author}}<button @click="replyTo=null">取消</button></div><el-input v-model="comment" type="textarea" :rows="3" placeholder="记录进展，或回复同事的留言…" maxlength="4000"/><el-button type="primary" :disabled="!comment.trim()" @click="postComment">发送留言</el-button><button class="ask-coo" :disabled="busy" @click="taskDrawer=false;runExample('comment','查看仓储任务的进展，帮我准备一条跟进留言。')"><el-icon><MagicStick/></el-icon>让 Coo 协助跟进</button></section></template></el-drawer>

    <el-drawer v-model="requirementDrawer" size="600px" title="需求详情" class="demo-overlay"><template v-if="selectedRequirement"><div class="drawer-kicker">{{selectedRequirement.id}}<span class="soft-tag" :class="selectedRequirement.status==='已分析'?'green':'gray'">{{selectedRequirement.status}}</span></div><h2 class="drawer-title">{{selectedRequirement.title}}</h2><h4 class="drawer-subtitle">原始需求</h4><p class="drawer-copy">{{selectedRequirement.raw}}</p><div v-if="selectedRequirement.status==='已分析'" class="analysis-sample"><div class="analysis-heading"><el-icon><MagicStick/></el-icon><strong>Coo 需求分析</strong><span>预设样例</span></div><h4>标准化需求</h4><p>{{selectedRequirement.title}}，明确责任人，并通过任务记录处理进展与结果。</p><h4>业务目标</h4><p>{{selectedRequirement.goal}}</p><div class="analysis-pair"><div><small>需求类型</small><strong>{{selectedRequirement.type}}</strong></div><div><small>建议优先级</small><strong>{{selectedRequirement.priority}}</strong></div><div><small>真伪判断</small><strong>真实需求</strong></div><div><small>重复判断</small><strong>暂无明确重复</strong></div></div><h4>判断依据</h4><p>有明确的员工使用场景、跨部门协作问题和预期结果。</p><h4>分析总结</h4><p>{{selectedRequirement.summary}}</p></div><div v-else class="analysis-empty"><el-icon><MagicStick/></el-icon><h3>让 Coo 帮你梳理需求</h3><p>点击后展示标准化内容、业务目标与优先级的预设样例。</p></div><div class="drawer-actions"><el-button type="primary" :loading="analyzing" @click="analyze(selectedRequirement)">{{selectedRequirement.status==='已分析'?'重新播放分析':'播放需求分析'}}</el-button><el-button :disabled="busy" @click="requirementDrawer=false;runExample('investigate',`围绕需求 ${selectedRequirement.title}，查询处理规范并准备跟进任务。`)">交给 Coo 跟进</el-button></div></template></el-drawer>

    <el-drawer v-model="knowledgeDrawer" size="580px" title="知识详情与来源" class="demo-overlay"><template v-if="selectedKnowledge"><div class="drawer-kicker">{{selectedKnowledge.category}}<span class="soft-tag gray">{{selectedKnowledge.scope}}</span></div><h2 class="drawer-title">{{selectedKnowledge.title}}</h2><p class="knowledge-version">v{{selectedKnowledge.version}} · {{selectedKnowledge.published?'已发布':'草稿'}} · {{selectedKnowledge.updated}}更新</p><div class="knowledge-body">{{selectedKnowledge.content}}</div><h4 class="drawer-subtitle">文档分段预览</h4><div v-for="(chunk,i) in selectedKnowledge.content.split('\n\n')" :key="i" class="knowledge-chunk"><small>片段 {{i+1}} · {{chunk.length}} 字符</small><p>{{chunk}}</p></div><div class="drawer-actions"><el-button type="primary" @click="publishKnowledge(selectedKnowledge)">{{selectedKnowledge.published?'停用演示知识':'演示发布'}}</el-button><el-button @click="recallDialog=true;recallDone=false">召回测试</el-button></div><p class="demo-footnote">仅展示知识阅读、分段与状态切换交互，不进行真实向量化。</p></template></el-drawer>

